    "description": "Talisman found inside the Auriza Hero's Grave . Reaching it is quite complex: From the first Chariot Hall, drop down through the opening on either side just before the second ramp. In the room below, head west and up the steps, then turn right into the next corridor that leads to a large hall with two Chariots running almost side by side, with a short delay between them. Head all the way down towards the pit behind the pillars. Looking down, you will see several wooden beams that you can drop onto. Navigate your way to the lowest beam and then head south towards the archway with a ladder at the back. Climb the ladder to reach a third Chariot Hall with a single Chariot. Head all the way down this hall, using the alcove on the left about halfway through to avoid the Chariot (unless you've previously destroyed it). At the bottom, turn left into a corridor and head straight to find a small room guarded by an Omen . The talisman can be found on a corpse behind the Omen, sitting by a statue.",
