const clean = (value: string) => value.toLowerCase().replace(/[+＋]\d+/g, "").replace(/[^a-z0-9' ]/g, " ").replace(/\s+/g, " ").trim();

export function findMapItems(value: string, preferredLayer?: MapItem["layer"], categoryPattern?: RegExp) {
  const query = clean(value);
  const candidates = mapItems
    .filter((item) => !categoryPattern || categoryPattern.test(item.category))
    .map((item) => ({ item, name: clean(item.name) }))
    .filter(({ name }) => name.length > 3 && (query.includes(name) || name.includes(query)))
    .sort((a, b) => Number(b.item.layer === preferredLayer) - Number(a.item.layer === preferredLayer) || b.name.length - a.name.length);
  const chosen: MapItem[] = [];
  const occupied: Array<[number, number]> = [];
  const names = new Set<string>();
  for (const candidate of candidates) {
    if (names.has(candidate.name)) continue;
    const start = query.indexOf(candidate.name);
    const end = start + candidate.name.length;
    if (start >= 0 && occupied.some(([from, to]) => start < to && end > from)) continue;
    chosen.push(candidate.item);
    names.add(candidate.name);
    if (start >= 0) occupied.push([start, end]);
  }
  return chosen;
}

export function findMapItem(value: string, preferredLayer?: MapItem["layer"]) {
  return findMapItems(value, preferredLayer)[0];
}

export function findMapRoutePoint(value: string, preferredLayer?: MapItem["layer"]) {
  const query = clean(value);
  if (query.length < 3) return undefined;
  const categoryPriority = (category: string) => /locations/i.test(category) ? 0 : /grace/i.test(category) ? 1 : /boss/i.test(category) ? 2 : /npc/i.test(category) ? 3 : 4;
  return mapRoutePoints
    .map((point) => { const name = clean(point.name); const match = name === query ? 0 : name.startsWith(query) ? 1 : query.startsWith(name) ? 2 : name.includes(query) ? 3 : query.includes(name) ? 4 : 99; return { point, match }; })
    .filter(({ point, match }) => match < 99 && (!preferredLayer || point.layer === preferredLayer))
    .sort((a, b) => a.match - b.match || categoryPriority(a.point.category) - categoryPriority(b.point.category) || a.point.name.length - b.point.name.length)[0]?.point;
}
